verus! {

    /// A helper predicate stating that three characters are pairwise distinct.
    spec fn happy_triple(c1: char, c2: char, c3: char) -> bool {
        c1 != c2 && c1 != c3 && c2 != c3
    }

    /// A predicate over immutable sequences of chars saying that
    /// 1) the length is at least 3, and
    /// 2) every contiguous window of size 3 is pairwise distinct.
    spec fn is_happy_seq(s: Seq<char>) -> bool {
        s.len() >= 3
        &&
        forall |i: nat| i + 2 < s.len() ==>
            happy_triple(s[i], s[i+1], s[i+2])
    }

    /// Specification for the vector‐based API.
    /// We simply relate the result to is_happy_seq on the underlying sequence.
    fn is_happy(s: Vec<char>) -> (result: bool)
        ensures
            // The function returns true exactly when the sequence is "happy"
            result == is_happy_seq(s.as_seq())
    {
        // If there are fewer than 3 characters, it can't be "happy".
        if s.len() < 3 {
            return false;
        }

        // Slide a window of size 3 across the vector.
        let mut i: usize = 0;
        while i + 2 < s.len() {
            // This decreases annotation shows progress for the verifier.
            decreases s.len() - i;

            let c1 = s[i];
            let c2 = s[i + 1];
            let c3 = s[i + 2];

            // If any pair in the triple is equal, it's not happy.
            if !(c1 != c2 && c1 != c3 && c2 != c3) {
                return false;
            }

            i += 1;
        }

        // Every triple was distinct, so it's happy.
        true
    }

}